INSERT INTO plans (name, badge, price, period, description, features, cta, popular, sort, published) SELECT 'Starter Website', 'STARTER PRESENCE', '6,999', 'one-time', 'For small shops and solo businesses that need a simple website, fast.', '["Custom 1-page high-converting landing page","100% mobile & tablet responsive","Direct WhatsApp click-to-chat button","Fast 5-day delivery","Google Maps location setup","Domain & hosting setup guidance"]', 'Choose Starter Plan', 0, 1, 1 WHERE NOT EXISTS (SELECT 1 FROM plans WHERE name = 'Starter Website');
INSERT INTO plans (name, badge, price, period, description, features, cta, popular, sort, published) SELECT 'Growth & Automation', 'GROWTH BUSINESS', '14,999', 'one-time', 'For clinics, coaching centres, salons and restaurants that want new enquiries every week.', '["Up to 5 custom high-conversion pages","Smart WhatsApp lead capture & auto-reply","Appointment / booking form","Local SEO & Google Business Profile setup","Super fast <1.5s loading speed","30 days free maintenance & updates","7-day launch guarantee"]', 'Get Growth Plan', 1, 2, 1 WHERE NOT EXISTS (SELECT 1 FROM plans WHERE name = 'Growth & Automation');
INSERT INTO plans (name, badge, price, period, description, features, cta, popular, sort, published) SELECT 'Full Digital Suite', 'SCALE & DOMINATE', '24,999', 'one-time', 'Website, WhatsApp automation and ads — everything you need to grow in your area.', '["Complete custom multi-page website","Advanced multi-step WhatsApp chatbot","Meta (Facebook & Instagram) ads setup","Ad creatives & copywriting","Meta Pixel & Conversions API tracking","60 days VIP priority support","Monthly analytics & performance report"]', 'Scale With Full Suite', 0, 3, 1 WHERE NOT EXISTS (SELECT 1 FROM plans WHERE name = 'Full Digital Suite');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'How fast will my website be live?', 'বেশিরভাগ প্রজেক্ট **৫ থেকে ৭ কাজের দিনের মধ্যে** লাইভ হয়ে যায়। একটা সিম্পল ১-পেজ Starter ওয়েবসাইট ৩-৪ দিনেই রেডি হতে পারে। লাইভ করার আগে আপনি একটা প্রাইভেট প্রিভিউ লিংক পাবেন, নিজের ফোনে দেখে নেওয়ার জন্য।', 1, 1, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How fast will my website be live?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'Do I need any technical knowledge?', 'একদমই না। ডোমেইন গাইডেন্স, হোস্টিং, SSL সিকিউরিটি, মোবাইল অপটিমাইজেশন, Google সেটআপ আর টেস্টিং — সব আমি সামলাই। আপনি শুধু WhatsApp-এ আপনার ব্যবসার ডিটেলস আর ছবি পাঠিয়ে দিন।', 1, 2, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Do I need any technical knowledge?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'Do I need to buy a domain and hosting myself?', 'আপনার আগে থেকেই ডোমেইন থাকলে আমরা সেটাই কানেক্ট করে দিই। না থাকলে আপনার নিজের নামে কিনতে আমি গাইড করব (সাধারণত বছরে ₹600–₹800), যাতে ওটা সবসময় আপনারই থাকে।', 0, 3, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Do I need to buy a domain and hosting myself?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'Do you work with businesses outside Purulia?', 'হ্যাঁ। আমি পুরুলিয়ার মানবাজারে থাকি, আর পুরো পশ্চিমবঙ্গ তো বটেই, সারা ভারতের ব্যবসার সঙ্গে কাজ করি। সব কাজ হয় WhatsApp, ফোন কল আর স্ক্রিন-শেয়ারে।', 0, 4, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Do you work with businesses outside Purulia?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'What exactly is lead generation?', 'এটা এমন একটা সিস্টেম যা অ্যাড, Google আর আপনার ওয়েবসাইটের মাধ্যমে আপনার সার্ভিসে আগ্রহী লোকেদের নিয়মিত আপনার কাছে নিয়ে আসে — আর তাঁদের নাম, ফোন নম্বর আর কী দরকার সেটা ধরে রাখে, যাতে আপনি তাঁদের কাস্টমার বানাতে পারেন।', 1, 5, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What exactly is lead generation?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'How does WhatsApp automation bring me more customers?', 'কেউ আপনার ওয়েবসাইট বা অ্যাডে ট্যাপ করলেই একটা রেডি মেসেজ সহ WhatsApp খুলে যায়। সঙ্গে সঙ্গে একটা অটো-রিপ্লাই একটা মেনু দিয়ে তাঁকে স্বাগত জানায় (সার্ভিস, দাম, বুকিং, টাইমিং) আর তাঁর ডিটেলস সেভ করে রাখে। আপনি ব্যস্ত ছিলেন বলে আর কোনো কাস্টমার হাতছাড়া হবে না।', 1, 6, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How does WhatsApp automation bring me more customers?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'Can I still chat normally with my customers?', 'হ্যাঁ। অটোমেশন শুধু প্রথম গ্রিটিং, মেনু আর লিড ক্যাপচারটা সামলায়। আপনি বা আপনার স্টাফ যখন খুশি যে কোনো চ্যাটে ঢুকে কথা বলতে পারেন।', 0, 7, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Can I still chat normally with my customers?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'Where do my leads go?', 'প্রতিটা লিড নিজে থেকেই একটা প্রাইভেট Google Sheet-এ সেভ হয়ে যায় — নাম, ফোন, কী দরকার আর কোথা থেকে এসেছে সহ। ফলে আপনি ফলো-আপ করতে পারেন আর বুঝতে পারেন কোনটা কাজ করছে।', 0, 8, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Where do my leads go?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '📣 Meta Ads (Facebook & Instagram)', 'How much should I spend on ads?', '5–15 কিমি রেডিয়াস টার্গেট করা লোকাল ব্যবসার জন্য **দিনে ₹200 থেকে ₹400** সাধারণত যথেষ্ট, নিয়মিত এনকোয়ারি পাওয়া শুরু করার জন্য। আমরা ছোট করে শুরু করি, মেপে দেখি, তারপর যেটা কাজ করছে সেটা বাড়াই।', 0, 9, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How much should I spend on ads?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '📣 Meta Ads (Facebook & Instagram)', 'Is the ad budget included in your price?', 'না — অ্যাডের খরচ আপনার নিজের অ্যাকাউন্ট থেকে সরাসরি Meta-কে দেওয়া হয়, যাতে কন্ট্রোল আপনার হাতেই থাকে। আমাদের ফি-তে থাকে সেটআপ, ক্রিয়েটিভ, অ্যাডের লেখা, টার্গেটিং আর ট্র্যাকিং।', 0, 10, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Is the ad budget included in your price?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'What are your payment terms?', 'কাজ শুরু করতে 50% অ্যাডভান্স, আর বাকি 50% লঞ্চের আগে, আপনি ডিজাইন দেখে অ্যাপ্রুভ করার পরেই। আমরা UPI আর ব্যাঙ্ক ট্রান্সফার নিই।', 0, 11, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What are your payment terms?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'Are there hidden monthly fees?', 'না। মূল প্যাকেজগুলো এককালীন পেমেন্ট। অ্যাড ম্যানেজমেন্ট বা মেইনটেন্যান্সের মতো মাসিক সার্ভিস পুরোপুরি অপশনাল — আপনি চাইলে তবেই।', 0, 12, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Are there hidden monthly fees?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'Is the ad budget included in the Full Digital Suite?', 'সুইটে সেটআপ, ডিজাইন, লেখা আর ট্র্যাকিং আছে। অ্যাডের খরচ আপনার নিজের অ্যাকাউন্ট থেকে সরাসরি Meta-কে যায়, তাই নিয়ন্ত্রণ আপনার হাতেই। বেশিরভাগ লোকাল ব্যবসা দিনে ₹200–₹400 দিয়ে শুরু করে।', 0, 13, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Is the ad budget included in the Full Digital Suite?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'Can I upgrade later?', 'হ্যাঁ। Starter দিয়ে শুরু করে পরে Growth বা Full Suite-এ যেতে পারেন — শুধু নতুন কাজের বাড়তি টাকাটা দেবেন।', 0, 14, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Can I upgrade later?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🛠️ After Launch', 'What if I need changes later?', 'প্রতিটা প্যাকেজে লঞ্চের পর ফ্রি সাপোর্ট থাকে (প্ল্যান অনুযায়ী 30–60 দিন)। দাম বদল, নতুন ছবি, পুজো বা উৎসবের অফার ব্যানার — শুধু একটা WhatsApp মেসেজ করে দিন।', 0, 15, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What if I need changes later?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🛠️ After Launch', 'Will my website show up on Google?', 'হ্যাঁ। প্রতিটা সাইট SEO-রেডি করে বানানো হয়, Google Search Console-এ সাবমিট করা হয় আর আপনার Google Business Profile-এর সঙ্গে কানেক্ট করা হয়, যাতে আশেপাশের কাস্টমাররা আপনাকে খুঁজে পান।', 0, 16, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Will my website show up on Google?');
